34: /* Called by a usbredirparser to log various messages */
35: enum { usbredirparser_none, usbredirparser_error, usbredirparser_warning,
36:        usbredirparser_info, usbredirparser_debug, usbredirparser_debug_data };
37: typedef void (*usbredirparser_log)(void *priv, int level, const char *msg);
