39: /* Called by a usbredirparser to read/write data to its peer.
40:    Must return the amount of bytes read/written, 0 when the read/write would
41:    block (and this is undesirable) and -1 on error.
42: 
43:    If the usbredirparser_fl_write_cb_owns_buffer flag is passed to
44:    usbredirparser_init, then the usbredirparser_write callback becomes
45:    the owner of the buffer pointed to by data and should call
46:    usbredirparser_free_write_buffer() when it is done with the buffer.
47:    In this case the callback is not allowed to return any amount of bytes
48:    written, it must either accept the entire buffer (return count),
49:    or signal blocking (return 0) or error (return -1). Returning any other
50:    value will result in a call to abort().
51: */
52: typedef int (*usbredirparser_read)(void *priv, uint8_t *data, int count);
53: typedef int (*usbredirparser_write)(void *priv, uint8_t *data, int count);
54: 
55: /* Locking functions for use by multithread apps */
56: typedef void *(*usbredirparser_alloc_lock)(void);
57: typedef void (*usbredirparser_lock)(void *lock);
58: typedef void (*usbredirparser_unlock)(void *lock);
59: typedef void (*usbredirparser_free_lock)(void *lock);
