142: /* Public part of the data allocated by usbredirparser_alloc, *never* allocate
143:    a usbredirparser struct yourself, it may be extended in the future to add
144:    callbacks for new packet types (which will then get added at the end),
145:    *and* usbredirparser_alloc will also allocate some space behind it for
146:    private data */
147: struct usbredirparser {
148:     /* app private data passed into all callbacks as the priv argument */
149:     void *priv;
150:     /* non packet callbacks */
151:     usbredirparser_log log_func;
152:     usbredirparser_read read_func;
153:     usbredirparser_write write_func;
154:     /* usb-redir-protocol v0.3 control packet complete callbacks */
155:     usbredirparser_device_connect device_connect_func;
156:     usbredirparser_device_disconnect device_disconnect_func;
157:     usbredirparser_reset reset_func;
158:     usbredirparser_interface_info interface_info_func;
159:     usbredirparser_ep_info ep_info_func;
160:     usbredirparser_set_configuration set_configuration_func;
161:     usbredirparser_get_configuration get_configuration_func;
162:     usbredirparser_configuration_status configuration_status_func;
163:     usbredirparser_set_alt_setting set_alt_setting_func;
164:     usbredirparser_get_alt_setting get_alt_setting_func;
165:     usbredirparser_alt_setting_status alt_setting_status_func;
166:     usbredirparser_start_iso_stream start_iso_stream_func;
167:     usbredirparser_stop_iso_stream stop_iso_stream_func;
168:     usbredirparser_iso_stream_status iso_stream_status_func;
169:     usbredirparser_start_interrupt_receiving start_interrupt_receiving_func;
170:     usbredirparser_stop_interrupt_receiving stop_interrupt_receiving_func;
171:     usbredirparser_interrupt_receiving_status interrupt_receiving_status_func;
172:     usbredirparser_alloc_bulk_streams alloc_bulk_streams_func;
173:     usbredirparser_free_bulk_streams free_bulk_streams_func;
174:     usbredirparser_bulk_streams_status bulk_streams_status_func;
175:     usbredirparser_cancel_data_packet cancel_data_packet_func;
176:     /* usb-redir-protocol v0.3 data packet complete callbacks */
177:     usbredirparser_control_packet control_packet_func;
178:     usbredirparser_bulk_packet bulk_packet_func;
179:     usbredirparser_iso_packet iso_packet_func;
180:     usbredirparser_interrupt_packet interrupt_packet_func;
181:     /* usbredir 0.3.2 new non packet callbacks (for multi-thread locking) */
182:     usbredirparser_alloc_lock alloc_lock_func;
183:     usbredirparser_lock lock_func;
184:     usbredirparser_unlock unlock_func;
185:     usbredirparser_free_lock free_lock_func;
