234: /* Call this whenever there is data ready from the other side to parse.
235:    On an usbredirparser_read_io_error this function will continue where it
236:    left of the last time on the next call. On an
237:    usbredirparser_read_parse_error it will skip to the next packet (*).
238:    *) As determined by the faulty package's headers length field */
239: enum {
240:     usbredirparser_read_io_error    = -1,
241:     usbredirparser_read_parse_error = -2,
242: };
243: int usbredirparser_do_read(struct usbredirparser *parser);
