248: /* This returns the number of bytes queued to be written out. Can be used by control plane
249:  * to drop data from being queued, see issue:
250:  * https://gitlab.freedesktop.org/spice/usbredir/-/issues/19 */ 
251: uint64_t usbredirparser_get_bufferered_output_size(struct usbredirparser *parser_pub);
252: 
253: /* Call this when usbredirparser_has_data_to_write returns > 0
254:    returns 0 on success, -1 if a write error happened.
255:    If a write error happened, this function will retry writing any queued data
256:    on the next call, and will continue doing so until it has succeeded! */
257: enum {
258:     usbredirparser_write_io_error   = -1,
259: };
260: int usbredirparser_do_write(struct usbredirparser *parser);
